  function log(msg) {
    const o = (typeof window !== 'undefined' && window.__HOCDERMA_PROPOSTAS_OPCOES__) || {};
    if (CONFIG.debug || o.debug) console.log('[Propostas HOC Derma] ' + msg);
  }
  function aviso(msg) { console.warn('[Propostas HOC Derma] ' + msg); }

  function opcoes() {
    const o = (typeof window !== 'undefined' && window.__HOCDERMA_PROPOSTAS_OPCOES__) || {};
    return { somentePaciente: String(o.somentePaciente || '').trim(), modoTeste: !!o.modoTeste };
  }
  function hooks() { return (typeof window !== 'undefined' && window.__HOCDERMA_PROPOSTAS_HOOKS__) || {}; }

  const fmtBRL = (() => {
    const f = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
    return (v) => f.format(Number.isFinite(v) ? v : 0);
  })();
  const fmtNum = (v) => (Number.isFinite(v) ? v : 0).toLocaleString('pt-BR',
    { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtPct = (v) => (Number.isFinite(v) ? v : 0).toLocaleString('pt-BR', { maximumFractionDigits: 2 });

  // "R$ 1.980,00" → 1980 | "10" → 10 | "10.5" → 10.5 | "1.980,5" → 1980.5
  function lerValor(txt) {
    let s = String(txt == null ? '' : txt).replace(/[^\d,.-]/g, '');
    if (!s) return 0;
    if (s.indexOf(',') >= 0) s = s.replace(/\./g, '').replace(',', '.');
    else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); // "1.980" sem centavos
    const n = parseFloat(s);
    return Number.isFinite(n) ? n : 0;
  }
  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  const arred = (v) => Math.round((v + Number.EPSILON) * 100) / 100;

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, (c) =>
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  }
  const limpa = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();

  function hojeBR(d) {
    const x = d || new Date();
    return String(x.getDate()).padStart(2, '0') + '/' + String(x.getMonth() + 1).padStart(2, '0') + '/' + x.getFullYear();
  }
  // data base "dd/mm/aaaa" + dias
  function somarDias(baseBR, dias) {
    const m = String(baseBR || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
    const d = m ? new Date(+m[3], +m[2] - 1, +m[1]) : new Date();
    d.setDate(d.getDate() + (parseInt(dias, 10) || 0));
    return d;
  }

  function featureAtiva() {
    try {
      if (typeof GM_getValue === 'function') return !!GM_getValue(CHAVE_FEATURE, true); // eslint-disable-line no-undef
    } catch (e) { /* fora do Tampermonkey ou @grant none */ }
    return true;
  }

  function q(raiz, sel) { try { return raiz.querySelector(sel); } catch (e) { return null; } }
  function qa(raiz, sel) { try { return Array.from(raiz.querySelectorAll(sel)); } catch (e) { return []; } }
  // ids dinâmicos: busca DENTRO do form (o Feegow troca o form por AJAX)
  function porId(raiz, id) { return q(raiz, '[id="' + String(id).replace(/"/g, '') + '"]'); }

  function textoOpcao(sel) {
    if (!sel || !sel.options) return '';
    const o = sel.options[sel.selectedIndex];
    if (!o) return '';
    const v = String(o.value == null ? '' : o.value).trim();
    const t = limpa(o.text);
    if (!t || v === '' || v === '0' || /^selecione/i.test(t)) return '';
    return t;
  }

  function paramsUrl(href) {
    const out = {};
    const juntar = (qs) => new URLSearchParams(qs).forEach((v, k) => { out[k.toLowerCase()] = v; });
    try {
      const u = new URL(href);
      juntar(u.search);
      const h = u.hash || '';
      const i = h.indexOf('?');
      if (i >= 0) juntar(h.slice(i + 1));
    } catch (e) { /* href inválido */ }
    return out;
  }

  /* --------------------------------------------------------------------------
   * 2.1 PREFERÊNCIAS DO MODAL (lembradas entre impressões)
   *     Só o armazenamento GM do PRÓPRIO script (nunca cookies/storage do site).
   * ------------------------------------------------------------------------ */

  const PREF_CHAVE = 'hoc_propostas_prefs';
  // padrões pedidos pelo Nicolas (20/11): validade ligada; colunas de desconto e acréscimo desligadas
  const PREF_PADRAO = {
    mostrarValidade: true,
    mostrarDescontoPorItem: false,
    mostrarAcrescimo: false,
    mostrarAssinatura: true,
    ocultarTabela: true, // v1.3.0: padrão SEM tabela; mostrar fica lembrado no PC
    mostrarTotal: true,
    incluirDescricoes: true,
    posicaoDescricoes: 'depois', // v1.2.2: sem efeito (ordem fixa: descrições antes da tabela e do total)
    valorNasDescricoes: true,    // tabela oculta: valor do procedimento abaixo de cada descrição
    salvarAoDesconto: true       // v1.4.9: ao aplicar o desconto total no Feegow, salva a proposta (se o total conferir)
  };
  const PREF_VERSAO = 130;
  let prefsMemoria = null;

  function lerPrefs() {
    let salvo = null;
    try {
      if (typeof GM_getValue === 'function') salvo = GM_getValue(PREF_CHAVE, null); // eslint-disable-line no-undef
    } catch (e) { salvo = null; }
    if (salvo == null) salvo = prefsMemoria;
    if (typeof salvo === 'string') { try { salvo = JSON.parse(salvo); } catch (e) { salvo = null; } }
    const out = Object.assign({}, PREF_PADRAO);
    if (salvo && typeof salvo === 'object') {
      Object.keys(PREF_PADRAO).forEach((k) => { if (typeof salvo[k] === typeof PREF_PADRAO[k]) out[k] = salvo[k]; });
      // preferências gravadas antes da v1.3.0 salvavam "tabela visível" sem a pessoa escolher:
      // nelas vale o novo padrão (sem tabela)
      if (!(salvo._v >= PREF_VERSAO)) out.ocultarTabela = PREF_PADRAO.ocultarTabela;
    }
    if (out.posicaoDescricoes !== 'antes') out.posicaoDescricoes = 'depois';
    return out;
  }

  function salvarPrefs(d) {
    const p = { _v: PREF_VERSAO };
    Object.keys(PREF_PADRAO).forEach((k) => { p[k] = d[k]; });
    prefsMemoria = p;
    try {
      if (typeof GM_setValue === 'function') GM_setValue(PREF_CHAVE, JSON.stringify(p)); // eslint-disable-line no-undef
    } catch (e) { /* sem GM: fica só na memória */ }
    return p;
  }

  function limparPrefs() {
    prefsMemoria = null;
    try {
      if (typeof GM_setValue === 'function') GM_setValue(PREF_CHAVE, ''); // eslint-disable-line no-undef
    } catch (e) { /* noop */ }
  }

