  // famPoppins = família da parte no "Padrão Poppins" (sem ela: Poppins)
  const FONTE_BLOCOS = [
    { id: 'cabecalho', rotulo: 'Título e dados do paciente', sel: 'h1, .dados', base: 10, poppins: 9.5 },
    { id: 'procTitulo', rotulo: 'Títulos dos procedimentos', sel: '.proc h3.tit, .desc-tit', base: 13.5, poppins: 13.5, famPoppins: 'original' },
    { id: 'descricao', rotulo: 'Descrições dos procedimentos', sel: '.proc .txt, .lista-outros', base: 9.8, poppins: 9.3 },
    { id: 'investimento', rotulo: 'Investimento (valor de cada descrição)', sel: '.proc .val', base: 12, poppins: 11 },
    { id: 'tabela', rotulo: 'Tabela de valores', sel: 'table.itens', base: 10.5, poppins: 9.5, herda: true },
    { id: 'totais', rotulo: 'Totais', sel: '.totais', base: 10, poppins: 9.5 },
    { id: 'pagamento', rotulo: 'Forma de pagamento, texto complementar e validade', sel: '.bloco', base: 10.5, poppins: 10, herda: true },
    { id: 'assinatura', rotulo: 'Assinatura / "Proposta elaborada por"', sel: '.assin, .gerado', base: 8.5, poppins: 8 },
    { id: 'legal', rotulo: 'Rodapé (texto legal)', sel: '.legal', base: 7.5, poppins: 7 }
  ];
  // 'original' = a família que a parte tinha na 1.3.6
  const FAMILIAS = [
    { id: 'poppins', nome: 'Poppins', css: "'HOCD Poppins','Segoe UI',Arial,sans-serif" },
    { id: 'montserrat', nome: 'Montserrat', css: "'HOCD Montserrat','Segoe UI',Arial,sans-serif" },
    { id: 'opensans', nome: 'Open Sans', css: "'HOCD Open Sans','Segoe UI',Arial,sans-serif" },
    { id: 'roboto', nome: 'Roboto', css: "'HOCD Roboto','Segoe UI',Arial,sans-serif" },
    { id: 'lato', nome: 'Lato', css: "'HOCD Lato','Segoe UI',Arial,sans-serif" },
    { id: 'arial', nome: 'Arial', css: 'Arial,Helvetica,sans-serif' },
    { id: 'times', nome: 'Times New Roman', css: "'Times New Roman',Times,serif" },
    { id: 'original', nome: 'Original (1.3.6)', css: null }
  ];
  const familia = (id) => FAMILIAS.find((x) => x.id === id);
  const nomeFaceCss = (id) => (familia(id) ? familia(id).css.split(',')[0].replace(/'/g, '') : '');
  let fontesMemoria = null;
  const fonteBloco = (id) => FONTE_BLOCOS.find((b) => b.id === id);
  const limitarFonte = (v) => Math.min(FONTE_MAX, Math.max(FONTE_MIN, Math.round(num(v) * 10) / 10));
  const padraoPt = (base, b) => (base === 'original' ? b.base : b.poppins);
  const padraoFam = (base, b) => (base === 'original' ? 'original' : (b.famPoppins || 'poppins'));
  // v1.3.9: formato salvo (_v). Antes (sem _v), o título dos procedimentos no Padrão Poppins era
  // Poppins 12,5 pt: quem tinha mudado só a fonte ou só o tamanho dele mantém a outra metade
  const FONTES_VERSAO = 2;
  const FONTES_PADRAO_V1 = { procTitulo: { tam: 12.5, fam: 'poppins' } };
  function migrarFontes(salvo) {
    if (!salvo || typeof salvo !== 'object' || salvo._v >= FONTES_VERSAO || salvo.base === 'original') return salvo;
    const tam = Object.assign({}, salvo.tam && typeof salvo.tam === 'object' ? salvo.tam : {});
    const fam = Object.assign({}, salvo.fam && typeof salvo.fam === 'object' ? salvo.fam : {});
    Object.keys(FONTES_PADRAO_V1).forEach((id) => {
      if (tam[id] == null && fam[id] == null) return; // estava no padrão: segue o padrão novo
      if (tam[id] == null) tam[id] = FONTES_PADRAO_V1[id].tam;
      if (fam[id] == null) fam[id] = FONTES_PADRAO_V1[id].fam;
    });
    return Object.assign({}, salvo, { tam, fam, _v: FONTES_VERSAO });
  }

  // { base:'poppins'|'original', tam:{id:pt}, fam:{id:familia} } (só o que difere da predefinição)
  function normalizarFontes(salvo) {
    const out = { base: 'poppins', tam: {}, fam: {} };
    if (!salvo || typeof salvo !== 'object') return out;
    if (salvo.base === 'original') out.base = 'original';
    const tam = salvo.tam && typeof salvo.tam === 'object' ? salvo.tam : {};
    const fam = salvo.fam && typeof salvo.fam === 'object' ? salvo.fam : {};
    FONTE_BLOCOS.forEach((b) => {
      const v = Number(tam[b.id]);
      if (Number.isFinite(v) && v > 0 && limitarFonte(v) !== padraoPt(out.base, b)) out.tam[b.id] = limitarFonte(v);
      const fa = String(fam[b.id] || '');
      if (familia(fa) && fa !== padraoFam(out.base, b)) out.fam[b.id] = fa;
    });
    return out;
  }
  function lerFontes() {
    let salvo = null;
    try {
      if (typeof GM_getValue === 'function') salvo = GM_getValue(FONTES_CHAVE, null); // eslint-disable-line no-undef
    } catch (e) { salvo = null; }
    if (salvo == null || salvo === '') salvo = fontesMemoria;
    if (typeof salvo === 'string') { try { salvo = JSON.parse(salvo); } catch (e) { salvo = null; } }
    return normalizarFontes(migrarFontes(salvo));
  }
  function salvarFontes(f) {
    const p = normalizarFontes(f);
    fontesMemoria = Object.assign({ _v: FONTES_VERSAO }, p);
    try {
      if (typeof GM_setValue === 'function') GM_setValue(FONTES_CHAVE, JSON.stringify(fontesMemoria)); // eslint-disable-line no-undef
    } catch (e) { /* sem GM: fica só na memória */ }
    return p;
  }
  // predefinição geral: substitui todos os ajustes
  const aplicarPredefinicaoFontes = (base) => salvarFontes({ base: base === 'original' ? 'original' : 'poppins', tam: {}, fam: {} });
  const limparFontes = () => aplicarPredefinicaoFontes('poppins');
  const tamanhoFonte = (f, id) => { const b = fonteBloco(id); return f.tam[id] != null ? f.tam[id] : padraoPt(f.base, b); };
  const familiaFonte = (f, id) => f.fam[id] || padraoFam(f.base, fonteBloco(id));
  const fontesOriginaisPuras = (f) => f.base === 'original' && !Object.keys(f.tam).length && !Object.keys(f.fam).length;
  const familiasUsadas = (f) => {
    const s = new Set();
    if (f.base === 'poppins') s.add('poppins');
    FONTE_BLOCOS.forEach((b) => { const fa = familiaFonte(f, b.id); if (FONTES_FACES[fa]) s.add(fa); });
    return Array.from(s).filter((x) => FONTES_FACES[x]);
  };

  function fontFaceCss(ids) {
    return ids.map((id) => (FONTES_FACES[id] || []).map(([arq, peso, estilo]) =>
      `@font-face{ font-family:'${nomeFaceCss(id)}'; font-style:${estilo}; font-weight:${peso}; font-display:block;` +
      ` src:url(data:font/woff2;base64,${FONTES_WOFF2[arq]}) format('woff2'); }`).join('\n')).join('\n');
  }

  function cssComFontes(css, f) {
    f = f || lerFontes();
    if (fontesOriginaisPuras(f)) return css; // "Padrão original": CSS da 1.3.6 intacto
    let out = String(css).replace(/font-size:\s*(\d+(?:\.\d+)?)pt/g, 'font-size:calc($1pt * var(--fk, 1))');
    if (f.base === 'poppins') out += '\n      body{ font-family:' + familia('poppins').css + '; }';
    FONTE_BLOCOS.forEach((b) => {
      const k = Math.round(tamanhoFonte(f, b.id) / b.base * 10000) / 10000;
      out += '\n      ' + b.sel + '{ --fk:' + k + ';' + (b.herda ? ' font-size:calc(10.5pt * var(--fk, 1));' : '') + ' }';
      const fa = familiaFonte(f, b.id);
      if (fa === 'original') {
        if (f.base !== 'original') out += '\n      ' + b.sel + '{ font-family:' + FONTE_FOLHA_ORIGINAL + '; }';
      } else {
        const todos = b.sel.split(',').map((x) => x.trim()).map((x) => x + ', ' + x + ' *').join(', ');
        out += '\n      ' + todos + '{ font-family:' + familia(fa).css + ' !important; }';
        // Poppins & cia. têm ascendentes altos: com line-height 1.15 o título (h3) passaria da caixa
        // e, no topo da folha, encostaria no cabeçalho do timbrado
        if (b.id === 'procTitulo') out += '\n      .proc h3.tit{ line-height:1.4; }';
      }
    });
    return fontFaceCss(familiasUsadas(f)) + '\n' + out;
  }
  const familiasCssDoDoc = (f) => familiasUsadas(f || lerFontes()).map(nomeFaceCss).join('|');

  // espera as fontes embutidas carregarem antes de medir/paginar/imprimir (limite 3 s)
  function esperarFontes(doc) {
    try {
      const fs = doc && doc.fonts;
      if (!fs || typeof fs.load !== 'function') return Promise.resolve();
      const nomes = String((doc.documentElement && doc.documentElement.getAttribute('data-fontes')) || '').split('|').filter(Boolean);
      const cargas = [];
      nomes.forEach((n) => ['400', '700'].forEach((w) => cargas.push(fs.load(w + ' 12px "' + n + '"', 'Ação R$ 1.234,56').catch(() => null))));
      const pronto = Promise.all(cargas).then(() => fs.ready);
      return Promise.race([pronto, new Promise((r) => setTimeout(r, 3000))]).then(() => undefined);
    } catch (e) { return Promise.resolve(); }
  }

  // janela (Shadow DOM) na fonte da predefinição: @font-face no documento (não vale dentro do shadow)
  function aplicarFonteJanela() {
    const f = lerFontes();
    const host = document.getElementById(ID_ROOT);
    if (f.base === 'poppins' && !document.getElementById('hocderma-propostas-fontes')) {
      const st = document.createElement('style');
      st.id = 'hocderma-propostas-fontes';
      st.textContent = fontFaceCss(['poppins']);
      (document.head || document.documentElement).appendChild(st);
    }
    if (host) host.style.setProperty('--hocd-fonte', f.base === 'poppins' ? familia('poppins').css : FONTE_UI_ORIGINAL);
  }

  /* --------------------------------------------------------------------------
   * 2.1.1 CONFIGURAÇÕES DO PC (v1.3.0): nome/cargo no fim da folha
   *       Gravadas no Tampermonkey daquele PC (GM_setValue). Nome vazio = automático
   *       ("Criado por" da proposta no Feegow; sem ele, o profissional).
   * ------------------------------------------------------------------------ */

  const CFG_CHAVE = 'hoc_propostas_config';
  const CFG_PADRAO = { nomeFinal: '', cargoFinal: '' };
  let cfgMemoria = null;

  function lerConfig() {
    let salvo = null;
    try {
      if (typeof GM_getValue === 'function') salvo = GM_getValue(CFG_CHAVE, null); // eslint-disable-line no-undef
    } catch (e) { salvo = null; }
    if (salvo == null) salvo = cfgMemoria;
    if (typeof salvo === 'string') { try { salvo = JSON.parse(salvo); } catch (e) { salvo = null; } }
    const out = Object.assign({}, CFG_PADRAO);
    if (salvo && typeof salvo === 'object') {
      Object.keys(CFG_PADRAO).forEach((k) => { if (typeof salvo[k] === 'string') out[k] = limpa(salvo[k]); });
    }
    return out;
  }
  function salvarConfig(c) {
    const p = {};
    Object.keys(CFG_PADRAO).forEach((k) => { p[k] = limpa((c || {})[k]); });
    cfgMemoria = p;
    try {
      if (typeof GM_setValue === 'function') GM_setValue(CFG_CHAVE, JSON.stringify(p)); // eslint-disable-line no-undef
    } catch (e) { /* sem GM: fica só na memória */ }
    return p;
  }
  function limparConfig() {
    cfgMemoria = null;
    try {
      if (typeof GM_setValue === 'function') GM_setValue(CFG_CHAVE, ''); // eslint-disable-line no-undef
    } catch (e) { /* noop */ }
  }

  /* --------------------------------------------------------------------------
   * 2.1.1 DESCRIÇÕES PERSONALIZADAS (v1.4.0) — "Gerenciar descrições"
   *     O catálogo DESCRICOES_PROCEDIMENTOS (acima) é o PADRÃO do script. O que a pessoa
   *     adiciona, edita ou exclui na tela "Gerenciar descrições" fica gravado neste PC
   *     (GM_setValue; sem GM, localStorage) e é mesclado POR CIMA do padrão, por id, a cada
   *     uso. Assim as atualizações do script não apagam nada: o padrão novo entra e as
   *     personalizações continuam valendo. Formato gravado:
   *       { formato:1, itens:{ [id]: { id, titulo, palavrasChave:[], texto, investimento,
   *                                    incluirPadrao, personalizado?, removido?, atualizadoEm } } }
   *     id igual ao de um item padrão = alteração dele (ou exclusão, se removido:true);
   *     id novo = item personalizado (id gerado, "x-...").
   * ------------------------------------------------------------------------ */

  const DESC_CHAVE = 'hoc_propostas_descricoes';
  const DESC_ULTIMO_CHAVE = 'hoc_propostas_descricoes_ultimo_backup';
  const DESC_FORMATO = 1;
  const DESC_TIPO = 'hoc-derma-descricoes';
  const DESC_CAMPOS = ['titulo', 'palavrasChave', 'texto', 'investimento', 'incluirPadrao'];
  const descMem = {}; // reserva em memória (chave → texto), quando GM e localStorage falham
  let descCache = null;

  function armLer(chave) {
    let s = null;
    try { if (typeof GM_getValue === 'function') s = GM_getValue(chave, null); } catch (e) { s = null; } // eslint-disable-line no-undef
    if (typeof s !== 'string' || !s) {
      try { s = window.localStorage.getItem(chave); } catch (e) { s = null; }
    }
    if (typeof s !== 'string' || !s) s = descMem[chave] || null;
    return s;
  }
  function armGravar(chave, texto) {
    descMem[chave] = texto;
    try { if (typeof GM_setValue === 'function') GM_setValue(chave, texto); } catch (e) { /* noop */ } // eslint-disable-line no-undef
    try { window.localStorage.setItem(chave, texto); } catch (e) { /* noop */ }
  }

  const ID_DESC_OK = /^[a-z0-9][a-z0-9_-]{0,79}$/i;
  // Entrada válida (ou null). Corta tamanhos e ignora campos desconhecidos.
  function descSanitizar(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const id = String(raw.id == null ? '' : raw.id).trim();
    if (!ID_DESC_OK.test(id)) return null;
    const out = { id };
    if (raw.removido === true) {
      out.removido = true;
    } else {
      out.titulo = String(raw.titulo == null ? '' : raw.titulo).replace(/\s+/g, ' ').trim().slice(0, 200);
      out.texto = String(raw.texto == null ? '' : raw.texto).replace(/\r/g, '').trim().slice(0, 20000);
      let pc = raw.palavrasChave;
      if (typeof pc === 'string') pc = pc.split(/\r?\n|;/);
      out.palavrasChave = (Array.isArray(pc) ? pc : []).map((p) => limpa(p).slice(0, 120)).filter(Boolean).slice(0, 100);
      out.investimento = limpa(raw.investimento).slice(0, 60);
      out.incluirPadrao = raw.incluirPadrao !== false;
      if (!out.titulo) return null;
    }
    if (raw.personalizado === true) out.personalizado = true;
    if (raw.atualizadoEm) out.atualizadoEm = String(raw.atualizadoEm).slice(0, 30);
    return out;
  }

  function descLer() {
    if (descCache) return descCache;
    let obj = null;
    const s = armLer(DESC_CHAVE);
    if (s) { try { obj = JSON.parse(s); } catch (e) { obj = null; } }
    const itens = {};
    if (obj && typeof obj === 'object' && obj.itens && typeof obj.itens === 'object') {
      Object.keys(obj.itens).forEach((k) => {
        const e = descSanitizar(Object.assign({}, obj.itens[k], { id: obj.itens[k] && obj.itens[k].id != null ? obj.itens[k].id : k }));
        if (e) itens[e.id] = e;
      });
    }
    descCache = { formato: DESC_FORMATO, itens };
    return descCache;
  }
  function descGravar(itens) {
    const est = { formato: DESC_FORMATO, itens: itens || {} };
    descCache = null;
    armGravar(DESC_CHAVE, JSON.stringify(est));
    return descLer();
  }

  function descPadraoMapa() {
    const m = new Map();
    DESCRICOES_PROCEDIMENTOS.forEach((e) => { if (e && e.id && !m.has(String(e.id))) m.set(String(e.id), e); });
    return m;
  }
  const descIgualCampos = (a, b) => JSON.stringify(DESC_CAMPOS.map((k) => a[k])) === JSON.stringify(DESC_CAMPOS.map((k) => b[k]));
  // campos padrão do script no mesmo formato das personalizações
  function descPadraoComoEntrada(e) {
    return descSanitizar({ id: e.id, titulo: e.titulo, palavrasChave: e.palavrasChave, texto: e.texto, investimento: e.investimento, incluirPadrao: e.incluirPadrao !== false }) ||
      { id: String(e.id), titulo: String(e.titulo || e.id), palavrasChave: [], texto: '', investimento: '', incluirPadrao: true };
  }

  // Catálogo efetivo = padrão do script + personalizações por cima (alterados, removidos, novos).
  function catalogoMesclado() {
    const ov = descLer().itens;
    const base = [];
    const vistos = new Set();
    DESCRICOES_PROCEDIMENTOS.forEach((e) => {
      if (!e || !e.id || vistos.has(String(e.id))) return;
      vistos.add(String(e.id));
      const o = ov[String(e.id)];
      if (o && o.removido) return;
      if (o) base.push(Object.assign({}, e, { titulo: o.titulo, palavrasChave: o.palavrasChave, texto: o.texto, investimento: o.investimento, incluirPadrao: o.incluirPadrao, exemplo: false, revisar: '' }));
      else base.push(e);
    });
    Object.keys(ov).forEach((id) => {
      const o = ov[id];
      if (vistos.has(id) || o.removido) return;
      base.push({ id: o.id, titulo: o.titulo, palavrasChave: o.palavrasChave, texto: o.texto, investimento: o.investimento, incluirPadrao: o.incluirPadrao });
    });
    return base;
  }

  // Linhas da tela: padrão (alterado ou não, ou excluído) + personalizados.
  function descLista() {
    const ov = descLer().itens;
    const out = [];
    const pad = descPadraoMapa();
    pad.forEach((e, id) => {
      const o = ov[id];
      if (o && o.removido) { const p = descPadraoComoEntrada(e); out.push(Object.assign({}, p, { origem: 'removido' })); return; }
      if (o) { out.push(Object.assign({}, o, { origem: 'alterado' })); return; }
      out.push(Object.assign({}, descPadraoComoEntrada(e), { origem: 'padrao' }));
    });
    Object.keys(ov).forEach((id) => { if (!pad.has(id) && !ov[id].removido) out.push(Object.assign({}, ov[id], { origem: 'personalizado' })); });
    return out;
  }

  function descNovoId(titulo) {
    const slug = normalizar(titulo).replace(/ /g, '-').slice(0, 40).replace(/-+$/, '') || 'item';
    const pad = descPadraoMapa();
    const ov = descLer().itens;
    for (let i = 0; i < 50; i++) {
      const id = 'x-' + slug + '-' + Math.random().toString(36).slice(2, 6);
      if (!pad.has(id) && !ov[id]) return id;
    }
    return 'x-' + slug + '-' + Date.now().toString(36);
  }

  // Cria (sem id) ou edita (com id). Retorna { ok, id } ou { ok:false, erro }.
  function descSalvarItem(dados) {
    const id = dados && dados.id ? String(dados.id) : descNovoId(dados && dados.titulo);
    const pad = descPadraoMapa();
    const e = descSanitizar({ id, titulo: dados.titulo, palavrasChave: dados.palavrasChave, texto: dados.texto, investimento: dados.investimento, incluirPadrao: dados.incluirPadrao, personalizado: !pad.has(id), atualizadoEm: new Date().toISOString() });
    if (!e) return { ok: false, erro: 'Informe o título (o identificador deve ter só letras, números, "-" e "_").' };
    if (!e.palavrasChave.length) return { ok: false, erro: 'Informe ao menos uma palavra ou frase para reconhecer o procedimento.' };
    if (!e.texto) return { ok: false, erro: 'Informe a descrição (o texto que sai na proposta).' };
    const itens = Object.assign({}, descLer().itens);
    if (pad.has(id) && descIgualCampos(e, descPadraoComoEntrada(pad.get(id)))) delete itens[id]; // igual ao padrão: sem personalização
    else itens[id] = e;
    descGravar(itens);
    return { ok: true, id };
  }
  // padrão: marca como excluído (volta com "Restaurar o padrão"); personalizado: apaga de vez
  function descExcluir(id) {
    id = String(id);
    const itens = Object.assign({}, descLer().itens);
    if (descPadraoMapa().has(id)) itens[id] = { id, removido: true, atualizadoEm: new Date().toISOString() };
    else delete itens[id];
    descGravar(itens);
    return true;
  }
  function descRestaurar(id) {
    id = String(id);
    if (!descPadraoMapa().has(id)) return false;
    const itens = Object.assign({}, descLer().itens);
    delete itens[id];
    descGravar(itens);
    return true;
  }

  // ---- backup ----
  const dataArquivo = () => {
    const d = new Date();
    const p = (n) => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes());
  };
  function descExportar() {
    const itens = Object.keys(descLer().itens).map((k) => descLer().itens[k]);
    return { tipo: DESC_TIPO, formato: DESC_FORMATO, script: VERSAO, geradoEm: new Date().toISOString(), itens };
  }
  const descNomeBackup = () => 'hoc-derma-descricoes-' + dataArquivo() + '.json';

  // Valida o texto de um backup. { ok, itens:[entradas] } ou { ok:false, erro }.
  function descValidarBackup(texto) {
    let obj;
    try { obj = JSON.parse(String(texto || '').replace(/^﻿/, '')); } catch (e) { return { ok: false, erro: 'O arquivo não é um JSON válido.' }; }
    if (!obj || typeof obj !== 'object' || Array.isArray(obj) || obj.tipo !== DESC_TIPO) return { ok: false, erro: 'Este arquivo não é um backup de descrições do HOC Derma.' };
    if (!Number.isInteger(obj.formato) || obj.formato < 1) return { ok: false, erro: 'O backup não informa a versão do formato.' };
    if (obj.formato > DESC_FORMATO) return { ok: false, erro: 'Backup de um formato mais novo (' + obj.formato + '). Atualize o script antes de restaurar.' };
    if (!Array.isArray(obj.itens)) return { ok: false, erro: 'O backup está sem a lista de itens.' };
    if (obj.itens.length > 2000) return { ok: false, erro: 'O backup tem itens demais.' };
    const itens = [];
    const ids = new Set();
    for (let i = 0; i < obj.itens.length; i++) {
      const e = descSanitizar(obj.itens[i]);
      if (!e) return { ok: false, erro: 'Item ' + (i + 1) + ' do backup inválido (título/identificador ausente ou fora do padrão).' };
      if (!e.removido && (!e.palavrasChave.length || !e.texto)) return { ok: false, erro: 'Item "' + e.titulo + '" do backup sem palavras para reconhecer ou sem descrição.' };
      if (ids.has(e.id)) return { ok: false, erro: 'Identificador repetido no backup: ' + e.id };
      ids.add(e.id);
      itens.push(e);
    }
    return { ok: true, itens, script: String(obj.script || ''), geradoEm: String(obj.geradoEm || '') };
  }

  const descChave = (e) => JSON.stringify(e.removido ? { id: e.id, removido: true } : { id: e.id, t: e.titulo, p: e.palavrasChave, x: e.texto, i: e.investimento, d: e.incluirPadrao });
  // Prévia do que muda: novos / alterados / removidos (só no "Substituir tudo") / iguais.
  function descPrevia(itensBackup) {
    const atual = descLer().itens;
    const novo = {};
    itensBackup.forEach((e) => { novo[e.id] = e; });
    const r = { novos: [], alterados: [], removidos: [], iguais: 0 };
    const nome = (e) => e.titulo || (descPadraoMapa().get(e.id) || {}).titulo || e.id;
    itensBackup.forEach((e) => {
      if (!atual[e.id]) r.novos.push({ id: e.id, titulo: nome(e), removido: !!e.removido });
      else if (descChave(atual[e.id]) !== descChave(e)) r.alterados.push({ id: e.id, titulo: nome(e) });
      else r.iguais++;
    });
    Object.keys(atual).forEach((id) => { if (!novo[id]) r.removidos.push({ id, titulo: nome(atual[id]) }); });
    return r;
  }
  // guarda o estado atual como "último backup automático" (e devolve o objeto)
  function descBackupAutomatico() {
    const b = descExportar();
    b.automatico = true;
    armGravar(DESC_ULTIMO_CHAVE, JSON.stringify(b));
    return b;
  }
  function descAplicarBackup(itensBackup, modo) {
    descBackupAutomatico();
    const itens = modo === 'substituir' ? {} : Object.assign({}, descLer().itens);
    itensBackup.forEach((e) => { itens[e.id] = e; });
    descGravar(itens);
    return descPrevia(itensBackup);
  }
  function descUltimoBackup() {
    const s = armLer(DESC_ULTIMO_CHAVE);
    if (!s) return null;
    const v = descValidarBackup(s);
    return v.ok ? Object.assign(v, { texto: s }) : null;
  }

  // ---- "Enviar para a lista padrão": só o que difere do padrão (novos + alterados + excluídos) ----
  function descTrechoCatalogo(entradas) {
    const js = (s) => JSON.stringify(String(s == null ? '' : s));
    return (entradas || []).filter((e) => !e.removido).map((e) => [
      '    {',
      '      id: ' + js(e.id.replace(/^x-/, '').replace(/-[a-z0-9]{4}$/, '') || e.id) + ',',
      '      titulo: ' + js(e.titulo) + ',',
      '      palavrasChave: [' + e.palavrasChave.map(js).join(', ') + '],',
      e.incluirPadrao === false ? '      incluirPadrao: false,' : null,
      '      investimento: ' + js(e.investimento) + ',',
      '      texto: ' + js(e.texto),
      '    }'
    ].filter((l) => l != null).join('\n')).join(',\n');
  }
  function descPacoteEnvio() {
    const itens = Object.keys(descLer().itens).map((k) => descLer().itens[k]);
    const pacote = { tipo: DESC_TIPO, formato: DESC_FORMATO, script: VERSAO, geradoEm: new Date().toISOString(), finalidade: 'para-lista-padrao', itens };
    return { pacote, trecho: descTrechoCatalogo(itens), qtd: itens.length };
  }

  // ---- lista de procedimentos do Feegow (colada/importada): linhas "ID - nome", "ID;nome", "ID<TAB>nome" ou só o nome ----
  function descLerListaFeegow(texto) {
    const out = [];
    const vistos = new Set();
    String(texto || '').replace(/^﻿/, '').split(/\r?\n/).forEach((ln) => {
      ln = ln.trim();
      if (!ln) return;
      let id = '';
      let nome = '';
      const cols = ln.split(/\t|;/).map((c) => c.trim().replace(/^"|"$/g, '').trim()).filter((c) => c !== '');
      if (cols.length >= 2) {
        if (/^\d+$/.test(cols[0])) { id = cols[0]; nome = cols[1]; } else nome = cols[0];
      } else {
        const m = ln.match(/^\[?(\d+)\]?\s*[-–:,]\s*"?(.+?)"?$/);
        if (m) { id = m[1]; nome = m[2]; } else nome = ln.replace(/^"|"$/g, '');
      }
      nome = limpa(nome);
      const k = normalizar(nome);
      if (!k || /^(procedimento|nome|id feegow|id)$/.test(k) || vistos.has(k)) return;
      vistos.add(k);
      out.push({ id, nome });
    });
    return out;
  }
  // procedimentos que NENHUMA entrada do catálogo (mesclado) reconhece
  function descSemDescricao(lista) {
    const cat = catalogo();
    return (lista || []).filter((p) => !entradasDoItem({ descricao: p.nome, codigoFeegow: p.id || '' }, cat).length);
  }

  /* --------------------------------------------------------------------------
   * 2.3 PROFISSIONAL COM TRATAMENTO, CRM E RQE (v1.4.8)
   *     "Profissional" da folha: "DRA. NOME COMPLETO · CRM nº/UF · RQE nº", lido em tempo de execução do
   *     cadastro do profissional no próprio Feegow (/main/?P=Profissionais&I=<id>&Pers=1, mesma origem,
   *     sessão logada, sem token). Nada disso fica gravado no script. Sem profissional na proposta, usa
   *     o cadastro da profissional "LINDA" (Dermatologia) entre as opções do campo Profissional.
   *     Dado que não existir no cadastro não é inventado: sai só o que houver (e a janela avisa o que falta).
   * ------------------------------------------------------------------------ */

  const PROF_PADRAO_PALAVRA = 'linda';
  const PROF_CACHE = new Map(); // id → dados do cadastro (null = leitura falhou)
  const PROF_PEND = new Map();
  const idProfissionalDoForm = (form) => {
    const sel = form && q(form, SEL.profissional);
    const v = sel ? String(sel.value || '').trim() : '';
    return /^\d+$/.test(v) && Number(v) > 0 ? String(Number(v)) : '';
  };
  function idProfissionalPadrao() {
    const sel = q(document, SEL.profissional);
    const o = sel && Array.from(sel.options || []).find((x) => /^\d+$/.test(String(x.value)) && normalizar(x.text).split(' ').indexOf(PROF_PADRAO_PALAVRA) >= 0);
    return o ? String(Number(o.value)) : '';
  }
  async function lerProfissionalFeegow(id) {
    const x = await fetch(baseFeegow() + '?P=Profissionais&I=' + encodeURIComponent(id) + '&Pers=1', { credentials: 'same-origin' });
    if (!x.ok) throw new Error('profissional ' + id + ': HTTP ' + x.status);
    const doc = new DOMParser().parseFromString(await textoDaResposta(x), 'text/html'); // documento inerte
    const val = (n) => { const e = doc.querySelector('[name="' + n + '"]'); return e ? limpa(e.value) : ''; };
    const opt = (n) => {
      const e = doc.querySelector('select[name="' + n + '"]');
      const o = e && e.options && e.options[e.selectedIndex];
      return o && String(o.value) !== '' && String(o.value) !== '0' && !/^selecione/i.test(o.text) ? limpa(o.text) : '';
    };
    const nome = val('NomeProfissional');
    if (!nome) throw new Error('cadastro do profissional ' + id + ' sem nome (página inesperada)');
    return { nome, tratamento: opt('TratamentoID'), sexo: opt('Sexo'), conselho: opt('Conselho'), documento: val('DocumentoConselho'), uf: val('UFConselho'), rqe: val('RQE') };
  }
  function profissionalPorId(id) {
    if (PROF_CACHE.has(id)) return Promise.resolve(PROF_CACHE.get(id));
    if (!PROF_PEND.has(id)) {
      PROF_PEND.set(id, lerProfissionalFeegow(id).then((r) => { PROF_CACHE.set(id, r); return r; })
        .catch((e) => { aviso('cadastro do profissional indisponível: ' + (e && e.message)); PROF_CACHE.set(id, null); return null; }));
    }
    return PROF_PEND.get(id);
  }
  // { texto, falta:[...] }: "DRA. NOME · CRM 123/SP · RQE 456" (só o que existir no cadastro)
  function formatarProfissional(info, nomeReserva) {
    let trat = limpa(info && info.tratamento);
    if (!trat) trat = /^fem/i.test(info && info.sexo) ? 'Dra.' : /^masc/i.test(info && info.sexo) ? 'Dr.' : '';
    const nome = limpa((info && info.nome) || nomeReserva).toUpperCase();
    const partes = [(trat ? trat.toUpperCase() + ' ' : '') + nome];
    const falta = [];
    if (info && info.documento) partes.push((info.conselho || 'CRM') + ' ' + info.documento + (info.uf ? '/' + info.uf : '')); else falta.push('CRM');
    if (info && info.rqe) partes.push('RQE ' + info.rqe); else falta.push('RQE');
    if (!trat) falta.push('tratamento (Dr./Dra.)');
    return { texto: partes.join(' · '), falta };
  }
  function mostrarInfoProfissional() {
    const el = S.shadow && S.shadow.querySelector('[data-prof-info]');
    const d = S.dados;
    if (el && d) el.textContent = d.profissionalFalta && d.profissionalFalta.length ? 'Faltam no cadastro do Feegow: ' + d.profissionalFalta.join(', ') + '.' : '';
  }
  // Ao abrir o editor: troca o nome simples pelo texto completo, se a pessoa ainda não mexeu no campo.
  async function carregarProfissionalDoEditor(d) {
    const original = limpa(d.profissional);
    const id = d.profissionalId || idProfissionalPadrao();
    if (!id) return;
    const info = await profissionalPorId(id);
    if (!info || S.dados !== d || limpa(d.profissional) !== original) return;
    const f = formatarProfissional(info, original);
    d.profissionalId = id;
    d.profissional = f.texto;
    d.profissionalFalta = f.falta;
    preencherCamposEditor();
    mostrarInfoProfissional();
    atualizar(true);
  }

  /* --------------------------------------------------------------------------
   * 2.2 DETECÇÃO DAS DESCRIÇÕES (catálogo × itens da proposta)
   * ------------------------------------------------------------------------ */

  // "Toxina Botulínica - Terço SUP." → "toxina botulinica terco sup"
  function normalizar(s) {
    return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '')
      .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  }
  const normCodigo = (c) => String(c == null ? '' : c).replace(/[^0-9a-z]/gi, '').toLowerCase().replace(/^0+(?=.)/, '');

  // palavras de ligação ignoradas na comparação
  const LIGACAO = new Set(['de', 'da', 'do', 'das', 'dos', 'e', 'com', 'para', 'a', 'o', 'as', 'os', 'em', 'no', 'na', 'ao', 'por']);
  let apelidosCache = null;
  function apelidosCompilados() {
    const chave = JSON.stringify(APELIDOS);
    if (apelidosCache && apelidosCache.chave === chave) return apelidosCache.lista;
    const lista = APELIDOS.filter((p) => p && normalizar(p[0]) && p[1] != null).map((p) => ({
      re: new RegExp('(^| )' + normalizar(p[0]) + '(?= |$)', 'g'),
      por: '$1' + normalizar(p[1])
    }));
    apelidosCache = { chave, lista };
    return lista;
  }
  // "BACIO LIP 03SS" → "baccio lip 3 sessoes" (só para COMPARAR; não muda o que é impresso)
  function normalizarBusca(s) {
    let n = ' ' + normalizar(s) + ' ';
    n = n.replace(/ 0*(\d+) ?ss(?= )/g, ' $1 sessoes ').replace(/ sessao(?= )/g, ' sessoes');
    n = n.replace(/ 0+(\d)/g, ' $1').replace(/\s+/g, ' ').trim();
    apelidosCompilados().forEach((a) => { n = n.replace(a.re, a.por); });
    return n.split(' ').filter((t) => t && !LIGACAO.has(t)).join(' ');
  }

  // distância de edição ≤ 1 (uma letra trocada, faltando ou sobrando)
  function quase(a, b) {
    if (a === b) return true;
    const la = a.length;
    const lb = b.length;
    if (Math.abs(la - lb) > 1) return false;
    let i = 0;
    while (i < la && i < lb && a[i] === b[i]) i++;
    if (la === lb) return a.slice(i + 1) === b.slice(i + 1);
    return la > lb ? a.slice(i + 1) === b.slice(i) : a.slice(i) === b.slice(i + 1);
  }

  // frase → [{ t: 'toxina', pref: false }, ...] ("peeling*" = prefixo)
  function compilarFrase(frase) {
    const bruto = String(frase || '');
    const prefixos = new Set(bruto.split(/\s+/).filter((w) => /\*+$/.test(w))
      .map((w) => normalizarBusca(w.replace(/\*+$/, '')).split(' ').pop()).filter(Boolean));
    return normalizarBusca(bruto.replace(/\*/g, ' ')).split(' ').filter(Boolean)
      .map((t) => ({ t, pref: prefixos.has(t) }));
  }

  function palavraCasa(f, n) {
    if (f.pref) return n.indexOf(f.t) === 0;
    if (n === f.t || n === f.t + 's' || f.t === n + 's') return true;
    // erro de digitação: só em palavras longas e nunca em números
    return f.t.length >= 6 && n.length >= 6 && !/\d/.test(f.t + n) && quase(f.t, n);
  }
  function fraseCasa(frase, tokensNome) {
    return frase.length > 0 && frase.every((f) => tokensNome.some((n) => palavraCasa(f, n)));
  }

  // v1.4.5: linhas de equipe (honorário de anestesista / 1º auxiliar) nunca recebem descrição de procedimento
  const EXCLUIR_EQUIPE = ['anestesista', 'auxiliar'];

  function catalogo() {
    const vistos = new Set();
    return catalogoMesclado().filter((e) => e && e.id && !vistos.has(e.id) && vistos.add(e.id)).map((e) => ({
      id: String(e.id),
      titulo: limpa(e.titulo) || String(e.id),
      texto: String(e.texto || '').replace(/\r/g, '').trim(),
      exemplo: !!e.exemplo,
      revisar: limpa(e.revisar),
      incluirPadrao: e.incluirPadrao !== false,
      investimento: limpa(e.investimento),
      valorModelo: valorDoInvestimento(e.investimento),
      frases: (e.palavrasChave || []).map(compilarFrase).filter((f) => f.length),
      excluir: (e.excluir || []).concat(EXCLUIR_EQUIPE).map(compilarFrase).filter((f) => f.length),
      codigos: (e.codigos || []).map(normCodigo).filter(Boolean)
    }));
  }

  function codigosDoItem(it) {
    const s = new Set();
    // o ID do Feegow só vale se a descrição não foi trocada no editor
    const mesmoItem = it.descricaoOriginal == null || limpa(it.descricaoOriginal) === limpa(it.descricao);
    if (mesmoItem && it.codigoFeegow && it.codigoFeegow !== '0') s.add(normCodigo(it.codigoFeegow));
    (String(it.descricao || '').match(/\b\d{5,}\b/g) || []).forEach((c) => s.add(normCodigo(c)));
    return s;
  }

  function entradasDoItem(it, cat) {
    const cods = codigosDoItem(it);
    const porCodigo = cat.filter((en) => en.codigos.some((c) => cods.has(c)));
    if (porCodigo.length) return porCodigo;
    const toks = normalizarBusca(it.descricao).split(' ').filter(Boolean);
    if (!toks.length) return [];
    const cand = [];
    cat.forEach((en) => {
      if (en.excluir.some((f) => fraseCasa(f, toks))) return;
      let melhor = null;
      en.frases.forEach((f) => { if (fraseCasa(f, toks) && (!melhor || f.length > melhor.length)) melhor = f; });
      if (melhor) cand.push({ en, frase: melhor });
    });
    // mais específico vence: se duas entradas casaram com frases que dividem alguma palavra
    // (mesma "família", ex.: "toxina botulinica" × "toxina terco superior"), fica só a de
    // frase mais longa. Frases sem palavra em comum (item combinado) ficam as duas.
    return cand.filter((a) => !cand.some((b) => b !== a && b.frase.length > a.frase.length &&
      a.frase.some((ta) => b.frase.some((tb) => tb.t === ta.t)))).map((x) => x.en);
  }

  // Retorna { blocos:[{id,titulo,texto,incluir,exemplo,editado,itens:[nomes],idx:[índices dos itens]}], semDescricao:[nomes] }.
  // "anteriores" preserva incluir/título/texto editados no modal.
  function detectarDescricoes(itens, anteriores) {
    const cat = catalogo();
    const prev = new Map(((anteriores && anteriores.blocos) || []).map((b) => [b.id, b]));
    const modoTeste = opcoes().modoTeste;
    const blocos = [];
    const porId = new Map();
    const sem = [];
    const semVistos = new Set();
    (itens || []).forEach((it, iItem) => {
      const nome = limpa(it.descricao);
      if (!nome) return;
      const ents = entradasDoItem(it, cat);
      if (!ents.length) {
        const k = normalizar(nome);
        if (!semVistos.has(k)) { semVistos.add(k); sem.push(nome); }
        return;
      }
      ents.forEach((en) => {
        let b = porId.get(en.id);
        if (!b) {
          const p = prev.get(en.id);
          const lembrado = investLembrado(en.id);
          b = p ? Object.assign({}, p, { itens: [], idx: [] }) : {
            id: en.id,
            titulo: en.titulo,
            texto: en.texto,
            tituloOriginal: en.titulo,
            textoOriginal: en.texto,
            exemplo: en.exemplo,
            revisar: en.revisar,
            incluir: (!en.exemplo || modoTeste) && en.incluirPadrao,
            editado: false,
            // "Investimento": valor do texto do modelo + fonte escolhida (lembrada por procedimento)
            investModelo: en.investimento,
            valorModelo: en.valorModelo,
            fonte: lembrado.fonte,
            manual: lembrado.manual,
            itens: [],
            idx: []
          };
          porId.set(en.id, b);
          blocos.push(b);
        }
        if (b.itens.indexOf(nome) < 0) b.itens.push(nome);
        b.idx.push(iItem);
      });
    });
    return { blocos, semDescricao: sem };
  }

  // Texto simples do catálogo → HTML seguro (parágrafos, listas, **negrito**).
  function textoParaHtml(txt) {
    const fmt = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    let out = '';
    let par = [];
    let lista = false;
    const fecharPar = () => { if (par.length) { out += '<p>' + par.map(fmt).join('<br>') + '</p>'; par = []; } };
    const fecharLista = () => { if (lista) { out += '</ul>'; lista = false; } };
    String(txt || '').replace(/\r/g, '').split('\n').forEach((l) => {
      const m = l.match(/^\s*[-•]\s+(.*)$/);
      const sub = l.match(/^\s*##\s+(.+)$/);
      if (m) { fecharPar(); if (!lista) { out += '<ul>'; lista = true; } out += '<li>' + fmt(m[1]) + '</li>'; }
      else if (sub) { fecharPar(); fecharLista(); out += tituloHtml(sub[1], 'h4', 'sub'); }
      else if (/^\s*-{3,}\s*$/.test(l)) { fecharPar(); fecharLista(); out += '<hr>'; }
      else if (!l.trim()) { fecharPar(); fecharLista(); }
      else { fecharLista(); par.push(l.trim()); }
    });
    fecharPar();
    fecharLista();
    return out;
  }

  // "LIFTERA | TERÇO MÉDIO E PAPADA | 03 SESSÕES" → procedimento + detalhes; "CORTESIA" vira selo
  function tituloHtml(titulo, tag, classe) {
    const partes = limpa(titulo).split(/\s*\|\s*/).filter(Boolean);
    const principal = partes.shift() || '';
    let cortesia = false;
    const detalhes = partes.map((p) => {
      if (!/cortesia/i.test(p)) return p;
      cortesia = true;
      return p.replace(/cortesia\s*[—–:-]?\s*/i, '').trim();
    }).filter(Boolean);
    return `<${tag} class="${classe}"><span class="t1">${esc(principal)}</span>${cortesia ? '<span class="selo">Cortesia</span>' : ''}` +
      `${detalhes.length ? `<span class="t2">${detalhes.map(esc).join(' <i>·</i> ')}</span>` : ''}</${tag}>`;
  }

  /* --------------------------------------------------------------------------
   * 2.3 INVESTIMENTO POR DESCRIÇÃO (Feegow × modelo × manual)
   * ------------------------------------------------------------------------ */

  const FONTES_INVEST = ['auto', 'feegow', 'modelo', 'manual', 'nenhum'];
  const INVEST_CHAVE = 'hoc_propostas_invest'; // { idDoBloco: { fonte, manual } }
  let investMemoria = {};

  // último valor em reais do texto ("de R$ 15.000,00 por R$ 12.000,00" → 12000)
  function valorDoInvestimento(s) {
    const m = String(s || '').match(/\d{1,3}(?:\.\d{3})*,\d{2}/g);
    return m ? lerValor(m[m.length - 1]) : null;
  }

  function lerInvestTodos() {
    let o = null;
    try {
      if (typeof GM_getValue === 'function') o = GM_getValue(INVEST_CHAVE, null); // eslint-disable-line no-undef
    } catch (e) { o = null; }
    if (o == null) return investMemoria;
    if (typeof o === 'string') { try { o = JSON.parse(o || '{}'); } catch (e) { o = {}; } }
    return o && typeof o === 'object' ? o : {};
  }
  function investLembrado(id) {
    const x = lerInvestTodos()[id] || {};
    return { fonte: FONTES_INVEST.indexOf(x.fonte) >= 0 ? x.fonte : 'auto', manual: typeof x.manual === 'string' ? x.manual : '' };
  }
  function salvarInvest(b) {
    const todos = Object.assign({}, lerInvestTodos());
    if ((b.fonte || 'auto') === 'auto' && !limpa(b.manual)) delete todos[b.id];
    else todos[b.id] = { fonte: b.fonte || 'auto', manual: String(b.manual || '') };
    investMemoria = todos;
    try {
      if (typeof GM_setValue === 'function') GM_setValue(INVEST_CHAVE, JSON.stringify(todos)); // eslint-disable-line no-undef
    } catch (e) { /* sem GM: fica só na memória */ }
  }
  function limparInvest() {
    investMemoria = {};
    try {
      if (typeof GM_setValue === 'function') GM_setValue(INVEST_CHAVE, ''); // eslint-disable-line no-undef
    } catch (e) { /* noop */ }
  }

  // v1.4.8: valor ATUAL do procedimento, lido na hora do próprio Feegow (mesma origem, sessão logada, sem
  // token): campo "Valor" da página do procedimento (/main/?P=Procedimentos&I=<id>&Pers=1). Cache por sessão.
  // A tabela VALORES_FEEGOW (v1.4.7) fica só de RESERVA, se a leitura falhar. Valor 0 = sem valor.
  const VALOR_ATUAL = new Map(); // id → reais (0 = sem valor)
  const VALOR_PEND = new Map(); // chave → Promise (uma leitura por procedimento por sessão)
  const ID_POR_NOME = new Map(); // nome normalizado → id ('' = não achou um nome exato)
  let timerValor = 0;
  const baseFeegow = () => location.origin + '/main/';
  async function textoDaResposta(x) {
    const ab = await x.arrayBuffer();
    try { return new TextDecoder('utf-8', { fatal: true }).decode(ab); } catch (e) { return new TextDecoder('windows-1252').decode(ab); }
  }
  // Mesma busca do select2 do campo Procedimento: POST sir.asp {q,page,t:'procedimentos',c:'NomeProcedimento',cs,exibir}.
  // Máx. 20 por termo; o item id -1 ("inserir novo cadastro") é ignorado. Só leitura.
  async function buscarProcsSir(termo) {
    const cv = document.getElementById('ConvenioID');
    const corpo = new URLSearchParams({ q: termo, page: '1', t: 'procedimentos', c: 'NomeProcedimento', cs: cv && cv.offsetParent !== null ? String(cv.value || '') : '', exibir: '' });
    const x = await fetch(baseFeegow() + 'sir.asp', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: corpo });
    if (!x.ok) throw new Error('busca de procedimentos: HTTP ' + x.status);
    const j = JSON.parse((await textoDaResposta(x)).trim());
    const vistos = new Set();
    return (j && Array.isArray(j.items) ? j.items : []).filter((i) => idProcValido(i.id))
      .map((i) => ({ id: String(Number(i.id)), nome: limpa(i.full_name) }))
      .filter((i) => i.nome && !vistos.has(i.id) && vistos.add(i.id));
  }
  async function lerValorAtual(id) {
    const x = await fetch(baseFeegow() + '?P=Procedimentos&I=' + encodeURIComponent(id) + '&Pers=1', { credentials: 'same-origin' });
    if (!x.ok) throw new Error('procedimento ' + id + ': HTTP ' + x.status);
    const doc = new DOMParser().parseFromString(await textoDaResposta(x), 'text/html'); // documento inerte: nada executa
    const inp = doc.querySelector('input[name="Valor"]');
    if (!inp) throw new Error('campo Valor não encontrado no procedimento ' + id);
    return arred(Math.max(0, lerValor(inp.value)));
  }
  function agendarValorAtual(it, pid) {
    const nome = normalizar(it.descricao);
    const k = pid || ('n:' + nome);
    if (VALOR_PEND.has(k) || (pid && VALOR_ATUAL.has(pid))) return;
    const p = (async () => {
      let id = pid;
      if (!id) {
        if (!nome) return;
        if (ID_POR_NOME.has(nome)) id = ID_POR_NOME.get(nome);
        else {
          const lst = await buscarProcsSir(limpa(it.descricao));
          const ex = lst.filter((x) => normalizar(x.nome) === nome);
          id = ex.length === 1 ? ex[0].id : '';
          ID_POR_NOME.set(nome, id);
        }
        if (!id) return;
      }
      if (!VALOR_ATUAL.has(id)) VALOR_ATUAL.set(id, await lerValorAtual(id));
    })().catch((e) => { aviso('valor atual do Feegow indisponível (usando a reserva): ' + (e && e.message)); })
      .then(() => { clearTimeout(timerValor); timerValor = setTimeout(() => { if (S.dados) atualizar(true); }, 200); });
    VALOR_PEND.set(k, p);
  }
  // espera (no máx. ms) as leituras de valor em andamento, para a impressão já sair com o valor atual
  function aguardarValoresAtuais(ms) {
    const ps = Array.from(VALOR_PEND.values()).concat(Array.from(PROF_PEND.values()));
    return ps.length ? Promise.race([Promise.all(ps), espera(ms)]) : Promise.resolve();
  }

  // Valor do procedimento no Feegow quando o item da proposta está sem valor: valor ATUAL (lido na hora) >
  // reserva embutida (VALORES_FEEGOW) pelo ID do item (só se o nome não foi trocado no editor) ou nome exato; 0 = sem valor.
  let valoresPorId = null;
  let valoresPorNome = null;
  function valorTabelaFeegow(it) {
    if (!it) return 0;
    if (!valoresPorId) {
      valoresPorId = new Map();
      valoresPorNome = new Map();
      VALORES_FEEGOW.forEach(([id, cent, nome]) => {
        valoresPorId.set(String(id), cent);
        valoresPorNome.set(nome, valoresPorNome.has(nome) && valoresPorNome.get(nome) !== cent ? -1 : cent);
      });
    }
    const mesmo = it.descricaoOriginal == null || limpa(it.descricaoOriginal) === limpa(it.descricao);
    const id = mesmo && it.codigoFeegow && it.codigoFeegow !== '0' ? String(Number(it.codigoFeegow)) : '';
    const pid = id || ID_POR_NOME.get(normalizar(it.descricao)) || '';
    if (pid && VALOR_ATUAL.has(pid)) return VALOR_ATUAL.get(pid);
    agendarValorAtual(it, pid);
    let cent = id ? valoresPorId.get(id) : 0;
    if (!cent) cent = valoresPorNome.get(normalizar(it.descricao)) || 0;
    return cent > 0 ? cent / 100 : 0;
  }
  // valor de RESERVA do item (valor atual do Feegow, senão a tabela embutida) × quantidade. Só para item SEM
  // valor na proposta (item com valor, inclusive cortesia com 100% de desconto, não usa). Ordem final do
  // "Investimento": valor da proposta > investimento do script (fixo ou "a partir de") > valor atual do
  // Feegow > tabela embutida. Por isso só é consultado quando o script não tem valor para o item.
  function reservaItem(it, total) {
    if (total > 0 || num(it.unitario) > 0) return 0;
    const v = valorTabelaFeegow(it);
    return v ? arred(v * (num(it.qtd) || 1)) : 0;
  }

  // Quem é "dono" de cada item: o 1º bloco impresso que casou com ele (o valor do item
  // aparece só ali, para a soma dos blocos bater com o total). Retorna
  // { blocosImp, dono: Map(iItem → bloco), info: Map(bloco → { meus, total, qtd, unit, incluidoEm }) }.
  function distribuirItens(d, c) {
    const blocosImp = d.incluirDescricoes ? (d.blocos || []).filter((b) => b.incluir && (limpa(b.titulo) || limpa(b.texto))) : [];
    const dono = new Map();
    blocosImp.forEach((b) => (b.idx || []).forEach((i) => {
      const it = d.itens[i];
      if (it && b.itens.indexOf(limpa(it.descricao)) >= 0 && !dono.has(i)) dono.set(i, b);
    }));
    const info = new Map();
    (d.blocos || []).forEach((b) => {
      const idx = (b.idx || []).filter((i, k, arr) => arr.indexOf(i) === k && d.itens[i]);
      const impresso = blocosImp.indexOf(b) >= 0;
      const meus = impresso ? idx.filter((i) => dono.get(i) === b) : idx.filter((i) => !dono.has(i));
      const total = arred(meus.reduce((s, i) => s + c.linhas[i].total, 0));
      const qtd = meus.length === 1 ? num(d.itens[meus[0]].qtd) : 0;
      const outro = meus.length ? null : idx.map((i) => dono.get(i)).find((x) => x && x !== b);
      const zerado = meus.length > 0 && !(total > 0) && meus.some((i) => num(d.itens[i].unitario) > 0);
      const reserva = () => arred(meus.reduce((s, i) => s + reservaItem(d.itens[i], c.linhas[i].total), 0));
      info.set(b, { meus, total, qtd, unit: qtd ? arred(total / qtd) : 0, incluidoEm: outro || null, zerado, reserva });
    });
    return { blocosImp, dono, info };
  }

  const textoManual = (s) => (/^\s*(r\$)?\s*[\d.]+(,\d{1,2})?\s*$/i.test(String(s || '')) ? fmtBRL(lerValor(s)) : limpa(s));

  // Resolve o "Investimento" do bloco: { fonte: efetiva, html, valor, temFeegow, dif }
  function investimentoDoBloco(b, inf) {
    const temFeegow = !!(inf && inf.meus.length);
    const feegowOk = temFeegow && inf.total > 0;
    const pedida = FONTES_INVEST.indexOf(b.fonte) >= 0 ? b.fonte : 'auto';
    let fonte = pedida;
    // v1.4.7: item com valor na proposta mas total 0 (cortesia / 100% de desconto) não ganha o valor do modelo
    const zerado = !!(inf && inf.zerado);
    let reserva = 0; // valor atual do Feegow / tabela embutida (v1.4.8): só quando a proposta e o script não têm valor
    const daReserva = () => { if (!zerado && inf && inf.reserva) reserva = inf.reserva(); return reserva > 0; };
    if (pedida === 'auto') {
      if (feegowOk) fonte = 'feegow';
      else if (inf && inf.incluidoEm) fonte = 'incluido';
      else if (!zerado && limpa(b.investModelo)) fonte = 'modelo';
      else fonte = daReserva() ? 'atual' : 'nenhum';
    } else if (pedida === 'feegow' && !feegowOk) fonte = inf && inf.incluidoEm ? 'incluido' : (daReserva() ? 'atual' : 'nenhum'); // v1.4.7: total 0 não mostra R$ 0,00
    else if (pedida === 'modelo' && !limpa(b.investModelo)) fonte = 'nenhum';
    else if (pedida === 'manual' && !limpa(b.manual)) fonte = 'nenhum';
    let html = '';
    let valor = null;
    if (fonte === 'feegow') {
      valor = inf.total;
      html = fmtBRL(inf.total) + (inf.qtd && inf.qtd !== 1 ? ` <small>(${esc(String(inf.qtd).replace('.', ','))} × ${fmtBRL(inf.unit)})</small>` : '');
    } else if (fonte === 'atual') {
      valor = reserva;
      html = fmtBRL(reserva) + (inf.qtd && inf.qtd !== 1 ? ` <small>(${esc(String(inf.qtd).replace('.', ','))} × ${fmtBRL(arred(reserva / inf.qtd))})</small>` : '');
    } else if (fonte === 'modelo') {
      valor = b.valorModelo;
      html = esc(b.investModelo);
    } else if (fonte === 'manual') {
      valor = valorDoInvestimento(textoManual(b.manual));
      html = esc(textoManual(b.manual));
    }
    const dif = feegowOk && b.valorModelo != null &&
      Math.abs(inf.total - b.valorModelo) > 0.009 && Math.abs((inf.unit || inf.total) - b.valorModelo) > 0.009;
    return { pedida, fonte, html, valor, temFeegow, feegowOk, dif };
  }

  /* --------------------------------------------------------------------------
   * 3. SANITIZAÇÃO DO TEXTO COMPLEMENTAR (HTML do CKEditor)
   *    Lista branca de tags; atributos só colspan/rowspan e alguns estilos.
   *    Parse num documento inerte (scripts não rodam, imagens não carregam).
   * ------------------------------------------------------------------------ */

  const TAGS_OK = new Set(['P', 'BR', 'B', 'STRONG', 'I', 'EM', 'U', 'S', 'UL', 'OL', 'LI', 'SPAN', 'DIV',
    'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'TABLE', 'THEAD', 'TBODY', 'TFOOT', 'TR', 'TD', 'TH',
    'BLOCKQUOTE', 'HR', 'SMALL', 'SUB', 'SUP']);
  const TAGS_DESCARTAR = new Set(['SCRIPT', 'STYLE', 'IFRAME', 'FRAME', 'OBJECT', 'EMBED', 'LINK', 'META', 'BASE',
    'TEMPLATE', 'NOSCRIPT', 'SVG', 'MATH', 'FORM', 'INPUT', 'BUTTON', 'SELECT', 'TEXTAREA', 'IMG', 'VIDEO',
    'AUDIO', 'SOURCE', 'CANVAS', 'TITLE', 'HEAD']);
  const ESTILOS_OK = /^(text-align|font-weight|font-style|text-decoration|text-indent|margin-left|padding-left)$/i;

  function sanitizarHtml(html) {
    const docInerte = document.implementation.createHTMLDocument('');
    const box = docInerte.createElement('div');
    box.innerHTML = String(html || '');
    const saida = docInerte.createElement('div');
    (function copiar(origem, destino) {
      Array.from(origem.childNodes).forEach((n) => {
        if (n.nodeType === 3) { destino.appendChild(docInerte.createTextNode(n.nodeValue)); return; }
        if (n.nodeType !== 1) return; // comentários etc.
        const tag = n.tagName.toUpperCase();
        if (TAGS_DESCARTAR.has(tag)) return;
        if (!TAGS_OK.has(tag)) { copiar(n, destino); return; } // desembrulha (a, font, o:p...)
        const el = docInerte.createElement(tag.toLowerCase());
        ['colspan', 'rowspan'].forEach((a) => {
          const v = n.getAttribute(a);
          if (v && /^\d{1,2}$/.test(v)) el.setAttribute(a, v);
        });
        const st = n.getAttribute('style');
        if (st) {
          const ok = st.split(';').map((d) => d.trim()).filter((d) => {
            const i = d.indexOf(':');
            if (i < 0) return false;
            const prop = d.slice(0, i).trim();
            const val = d.slice(i + 1).trim();
            return ESTILOS_OK.test(prop) && /^[\w\s.%#-]+$/.test(val);
          });
          if (ok.length) el.setAttribute('style', ok.join(';'));
        }
        copiar(n, el);
        destino.appendChild(el);
      });
    })(box, saida);
    return saida.innerHTML.replace(/(<p>(&nbsp;|\s|<br>)*<\/p>\s*)+$/i, '').trim();
  }

  function htmlParaTexto(html) {
    const d = document.implementation.createHTMLDocument('');
    const b = d.createElement('div');
    b.innerHTML = sanitizarHtml(html);
    return limpa(b.textContent);
  }

  /* --------------------------------------------------------------------------
   * 4. LEITURA DO form#frmProposta
   * ------------------------------------------------------------------------ */

  // Há DOIS elementos com id="PacienteID" (select desabilitado + hidden).
  function pacienteDoForm(form) {
    const els = qa(form, '[id="PacienteID"], [name="PacienteID"]');
    let id = '';
    let nome = '';
    els.forEach((el) => {
      if (el.tagName === 'SELECT') {
        if (!nome) nome = textoOpcao(el);
        if (!id && el.value && /^\d+$/.test(el.value)) id = el.value;
      } else if (el.tagName === 'INPUT') {
        if (el.value && /^\d+$/.test(el.value.trim())) id = el.value.trim(); // hidden vence
      }
    });
    if (!nome) {
      const c = q(form, '[id^="select2-PacienteID"][id$="-container"]');
      if (c) nome = limpa(c.getAttribute('title') || c.textContent);
    }
    return { id, nome };
  }

  function formatarNome(bruto, formato) {
    const s = limpa(bruto);
    if (formato !== 'nome_sobrenome' || s.indexOf(',') < 0) return s;
    const i = s.indexOf(',');
    const sobrenome = s.slice(0, i).trim();
    const nome = s.slice(i + 1).trim();
    return limpa(nome + ' ' + sobrenome);
  }

  function propostaIdDoForm(form) {
    const cands = qa(form, '[onclick*="PropostaID="], a[href*="PropostaID="]');
    for (const el of cands) {
      const m = String(el.getAttribute('onclick') || el.getAttribute('href') || '').match(/PropostaID=(\d+)/i);
      if (m) return m[1];
    }
    const h = q(form, 'input[name="PropostaID"], input[id="PropostaID"]');
    if (h && /^\d+$/.test(String(h.value).trim())) return String(h.value).trim();
    // script historicoProposta: ID: "28371"
    const scripts = qa(form, 'script').concat(qa(document, 'script'));
    for (const s of scripts) {
      const t = s.textContent || '';
      if (t.indexOf('historicoProposta') < 0) continue;
      const m = t.match(/\bID\s*:\s*["']?(\d+)/);
      if (m) return m[1];
    }
    return '';
  }

  // Quem criou a proposta: o Feegow mostra "Criado por NOME" em div#ListaPropostas (tab-pane).
  function criadoPorDaProposta(form) {
    const alvos = [document.getElementById('ListaPropostas'), form];
    for (const el of alvos) {
      if (!el) continue;
      const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
      const m = t.match(/Criad[oa] por\s+([A-Za-zÀ-ÿ'´`.\- ]+?)(?=\s+(?:em|no dia|às?)\s|\s*\d|\s*$)/i);
      if (m && m[1].trim()) return m[1].trim();
    }
    return '';
  }

  function profissionalDoForm(form) {
    const t = textoOpcao(q(form, SEL.profissional));
    if (t) return t;
    const c = q(form, SEL.profissionalSelect2);
    const v = c ? limpa(c.getAttribute('title') || c.textContent) : '';
    return /^selecione/i.test(v) ? '' : v;
  }

  // Total da linha conforme o Feegow. Modo 'linha': desconto/acréscimo em R$
  // valem para a linha toda; 'unidade': valem por unidade (× qtd).
  function calcLinha(it) {
    const qtd = num(it.qtd);
    const unit = num(it.unitario);
    const d = Math.max(0, num(it.desconto));
    const a = Math.max(0, num(it.acrescimo));
    const porUn = it.modo === 'unidade';
    const base = arred(qtd * unit);
    const descR = it.descontoTipo === 'P' ? arred(base * Math.min(d, 100) / 100) : arred(porUn ? d * qtd : d);
    const acrR = arred(porUn ? a * qtd : a);
    return { base, descR, acrR, total: arred(base - descR + acrR) };
  }

  // v1.3.2: id real da linha. Item JÁ SALVO: tr#row82910 / ItemID82910. Item NOVO (inserido por
  // AJAX, ainda não salvo): tr#row-82911, propostaItem = "-82911", ItemID-82911, mas data-val="82911"
  // (sem o "-"). Tenta tr.id sem "row", depois o propostaItem, depois o data-val, e fica com o
  // primeiro que tem os campos (ItemID/ValorUnitario/Quantidade) no form.
  function idDaLinha(form, tr) {
    const cands = [];
    const m = String(tr.id || '').match(/^row(-?\d+)$/i);
    if (m) cands.push(m[1]);
    const pi = q(tr, 'input[name="propostaItem"]');
    if (pi && /^-?\d+$/.test(String(pi.value).trim())) cands.push(String(pi.value).trim());
    const dv = String(tr.getAttribute('data-val') || '').trim();
    if (dv) { cands.push(dv); if (dv.charAt(0) !== '-') cands.push('-' + dv); }
    const ok = cands.find((c) => porId(form, 'ItemID' + c) || porId(form, 'ValorUnitario' + c) || porId(form, 'Quantidade' + c));
    return ok != null ? ok : (cands[0] || '');
  }

  function lerItens(form) {
    const tb = q(form, SEL.tbodyItens) || form;
    return qa(tb, SEL.linhaItem).filter((tr) => tr.id !== 'footItens').map((tr) => {
      const id = idDaLinha(form, tr);
      const sel = porId(form, 'ItemID' + id);
      let descricao = textoOpcao(sel);
      if (!descricao) {
        const c = porId(form, 'select2-ItemID' + id + '-container');
        descricao = c ? limpa(c.getAttribute('title') || c.textContent) : '';
      }
      const tipoSel = porId(form, 'DescontoTipo' + id);
      const tipoInput = q(tr, 'input.tipoItem, input[name="tipoItem' + id + '"]');
      const subEl = porId(form, 'sub' + id);
      const it = {
        idFeegow: id,
        tipo: tipoInput ? String(tipoInput.value || '') : '',
        descricao,
        descricaoOriginal: descricao,
        codigoFeegow: sel && /^[\w.-]+$/.test(String(sel.value || '')) && String(sel.value) !== '0' ? String(sel.value) : '',
        qtd: lerValor((porId(form, 'Quantidade' + id) || {}).value) || 1,
        unitario: lerValor((porId(form, 'ValorUnitario' + id) || {}).value),
        desconto: lerValor((porId(form, 'Desconto' + id) || {}).value),
        descontoTipo: tipoSel && String(tipoSel.value).toUpperCase() === 'P' ? 'P' : 'V',
        acrescimo: lerValor((porId(form, 'Acrescimo' + id) || {}).value),
        modo: 'linha',
        subFeegow: subEl ? lerValor(subEl.textContent || subEl.value) : null
      };
      // v1.3.2: item recém-adicionado pode vir com ValorUnitario "0,00" enquanto o Feegow já mostra o
      // total da linha (sub). Nesse caso deriva o unitário do sub (desfazendo desconto/acréscimo).
      if (!(it.unitario > 0) && it.subFeegow > 0) {
        const q1 = num(it.qtd) || 1;
        const d = Math.max(0, num(it.desconto));
        const a = Math.max(0, num(it.acrescimo));
        let u;
        if (it.descontoTipo === 'P') u = d < 100 ? (it.subFeegow - a) / (q1 * (1 - d / 100)) : 0;
        else u = (it.subFeegow - a + d) / q1;
        if (u > 0) { it.unitario = arred(u); it.unitarioDerivado = true; }
      }
      // Descobre o modo comparando com o total que o próprio Feegow mostra.
      if (it.subFeegow != null && it.qtd > 1) {
        const tl = calcLinha(it).total;
        const tu = calcLinha(Object.assign({}, it, { modo: 'unidade' })).total;
        if (Math.abs(tl - it.subFeegow) > 0.009 && Math.abs(tu - it.subFeegow) <= 0.009) it.modo = 'unidade';
      }
      return it;
    });
  }

  // Outras despesas: linhas do tbody ANTES de tr#PropostasOutros (estrutura
  // ainda não vista com dados: leitura heurística).
  function lerOutras(form) {
    const marc = q(form, SEL.marcadorOutros);
    if (!marc || !marc.parentNode) return [];
    const out = [];
    let tr = marc.previousElementSibling;
    const linhas = [];
    while (tr) { if (tr.tagName === 'TR') linhas.unshift(tr); tr = tr.previousElementSibling; }
    linhas.forEach((l) => {
      if (l.querySelector('th')) return;
      let descricao = '';
      let valor = 0;
      qa(l, 'select, input:not([type="hidden"]), textarea').forEach((c) => {
        if (c.id === ID_PROIBIDO) return;
        const v = c.tagName === 'SELECT' ? textoOpcao(c) : String(c.value || '').trim();
        if (!v) return;
        if (/^-?[\d.]+,\d{2}$/.test(v)) valor = lerValor(v);
        else if (!descricao && !/^\d+$/.test(v)) descricao = v;
      });
      if (!descricao) {
        const t = limpa(l.textContent);
        if (t && !/^r\$/i.test(t)) descricao = t.slice(0, 120);
      }
      if (descricao || valor) out.push({ descricao, valor });
    });
    return out;
  }

  function lerTextoComplementar(form) {
    let html = '';
    try {
      const ck = window.CKEDITOR && window.CKEDITOR.instances && window.CKEDITOR.instances[ID_CKEDITOR_TEXTO];
      if (ck && typeof ck.getData === 'function') html = String(ck.getData() || '');
    } catch (e) { html = ''; }
    // Rodando pela Suite (sandbox do Tampermonkey) o window.CKEDITOR da página não é visível:
    // lê direto o iframe do editor (mesma origem).
    if (!html) {
      try {
        const fr = document.querySelector('#cke_' + ID_CKEDITOR_TEXTO + ' iframe');
        const body = fr && fr.contentDocument && fr.contentDocument.body;
        if (body) html = String(body.innerHTML || '');
      } catch (e) { html = ''; }
    }
    if (!html) {
      const ta = q(form, SEL.textoComplementar);
      if (ta && ta.id !== ID_PROIBIDO) html = String(ta.value || '');
    }
    return sanitizarHtml(html);
  }

  function valorInput(form, sel, padrao) {
    const el = q(form, sel);
    const v = el ? limpa(el.value) : '';
    return v || padrao;
  }

  function lerProposta(form) {
    const pac = pacienteDoForm(form);
    const formas = qa(form, SEL.formasPagamento)
      .filter((t, i, arr) => arr.indexOf(t) === i && t.id !== ID_PROIBIDO)
      .map((t) => String(t.value || '').replace(/\r/g, '').replace(/[ \t]+$/gm, '').trim())
      .filter(Boolean);
    const pagamento = formas.join('\n\n');
    const totalEl = q(form, SEL.total);
    const valorEl = q(form, SEL.valorHidden);
    const totalFeegow = totalEl ? lerValor(totalEl.textContent) : (valorEl ? lerValor(valorEl.value) : null);
    const dataEl = q(form, SEL.data);
    const data = dataEl && /\d{2}\/\d{2}\/\d{4}/.test(dataEl.value) ? dataEl.value.trim() : hojeBR();
    const textoHtml = lerTextoComplementar(form);
    const d = {
      numero: propostaIdDoForm(form),
      pacienteId: pac.id,
      pacienteBruto: pac.nome,
      formatoNome: CONFIG.formatoNomePadrao,
      paciente: formatarNome(pac.nome, CONFIG.formatoNomePadrao),
      data,
      profissional: profissionalDoForm(form),
      profissionalId: idProfissionalDoForm(form),
      status: textoOpcao(q(form, SEL.status)),
      titulo: CONFIG.textos.titulo,
      tituloItens: valorInput(form, SEL.tituloItens, 'Procedimento'),
      tituloPagamento: valorInput(form, SEL.tituloPagamento, 'Forma de Pagamento'),
      tituloOutros: valorInput(form, SEL.tituloOutros, 'Outras Despesas'),
      itens: lerItens(form),
      descontoTotalPct: Math.min(100, Math.max(0, lerValor((q(form, SEL.descontoTotal) || {}).value))),
      descontoTotalTipo: 'P', // v1.3.6: desconto geral da janela em % (P) ou R$ (V)
      descontoTotalReais: 0,
      outras: lerOutras(form),
      pagamento,
      textoHtml,
      totalFeegow,
      validadeDias: CONFIG.textos.validadeDias,
      // a forma de pagamento do Feegow costuma já trazer "PROPOSTA VÁLIDA POR X DIAS"
      criadoPorAuto: criadoPorDaProposta(form),
      tituloDescricoes: CONFIG.textos.tituloDescricoes
    };
    // opções do modal (validade, colunas, assinatura, tabela, total, descrições): lembradas
    Object.assign(d, lerPrefs());
    // v1.3.0: nome/cargo no fim da folha: config do PC vence o automático
    const cfg = lerConfig();
    d.criadoPor = cfg.nomeFinal || d.criadoPorAuto;
    d.cargoFinal = cfg.cargoFinal;
    const det = detectarDescricoes(d.itens, null);
    d.blocos = det.blocos;
    d.semDescricao = det.semDescricao;
    return d;
  }

  function calcular(d) {
    const linhas = d.itens.map(calcLinha);
    const subtotal = arred(linhas.reduce((s, l) => s + l.total, 0));
    let pct;
    let descTotal;
    if (d.descontoTotalTipo === 'V') { // v1.3.6: desconto geral em R$ (pct equivalente com 2 casas)
      descTotal = arred(Math.min(subtotal, Math.max(0, num(d.descontoTotalReais))));
      pct = subtotal > 0 ? Math.min(100, Math.round(descTotal / subtotal * 10000) / 100) : 0;
    } else {
      pct = Math.min(100, Math.max(0, num(d.descontoTotalPct)));
      descTotal = arred(subtotal * pct / 100);
    }
    const outras = arred((d.outras || []).reduce((s, o) => s + num(o.valor), 0));
    const total = arred(subtotal - descTotal + (CONFIG.outrasSomamNoTotal ? outras : 0));
    return {
      linhas, subtotal, pct, descTotal, outras, total,
      temDesc: linhas.some((l) => l.descR > 0),
      temAcr: linhas.some((l) => l.acrR > 0)
    };
  }

  /* --------------------------------------------------------------------------
   * 5. BOTÃO "Imprimir HOC Derma" EM #btnsProposta
   * ------------------------------------------------------------------------ */

  function liberadoParaForm(form) {
    const o = opcoes();
    if (!o.somentePaciente) return true;
    const pac = pacienteDoForm(form);
    const urlI = String(paramsUrl(location.href).i || '').trim();
    if (pac.id !== o.somentePaciente) return false;     // o form PRECISA ser do paciente da trava
    if (urlI && urlI !== o.somentePaciente) return false; // e a URL não pode contradizer
    return true;
  }

  function criarBotao(form) {
    const b = document.createElement('button');
    b.type = 'button'; // NÃO submete o form
    b.className = 'btn btn-sm btn-danger ' + CLASSE_BOTAO;
    b.title = 'Salva a proposta no Feegow (SALVAR) e abre a impressão personalizada HOC Derma (as edições da janela valem só para a impressão)';
    b.setAttribute('data-hocderma', VERSAO);
    b.style.cssText = 'margin-left:4px;margin-right:4px;background-color:' + CONFIG.cores.botao +
      ';border-color:' + CONFIG.cores.botaoBorda + ';color:#fff;';
    b.innerHTML = '<i class="far fa-print"></i> Imprimir HOC Derma';
    b.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const f = b.closest(SEL.form) || form;
      clicarSalvarFeegow(f);
      abrirEditor(f);
    });
    return b;
  }

  // v1.3.5: antes de abrir a janela de impressão, clica no SALVAR do Feegow
  // (button onclick="propostaSave(false)") para a proposta ficar gravada.
  // Não espera o AJAX do salvamento nem bloqueia a impressão: o editor lê o DOM
  // na hora, e o propostaSave já serializou o form no clique.
  function acharBotaoSalvar(form) {
    const raizes = [];
    const barra = form && q(form, SEL.botoes);
    if (barra) raizes.push(barra);
    if (form) raizes.push(form);
    raizes.push(document);
    for (const r of raizes) {
      const b = q(r, 'button[onclick^="propostaSave(false)"]');
      if (b) return b;
    }
    // reservas só dentro da barra/form da proposta: outro onclick com propostaSave,
    // ou botão com texto SALVAR e ícone fa-save
    const locais = raizes.slice(0, raizes.length - 1);
    for (const r of locais) {
      const b = q(r, SEL.botaoSalvar);
      if (b) return b;
    }
    for (const r of locais) {
      const b = qa(r, 'button').find((x) => !x.classList.contains(CLASSE_BOTAO) &&
        /^\s*salvar\s*$/i.test(x.textContent || '') && x.querySelector('.fa-save'));
      if (b) return b;
    }
    return null;
  }

  function clicarSalvarFeegow(form) {
    const b = acharBotaoSalvar(form);
    if (!b) { log('botão SALVAR da proposta não encontrado; segue só a impressão.'); return false; }
    try { b.click(); log('SALVAR do Feegow clicado antes de imprimir.'); return true; } catch (e) {
      aviso('falha ao clicar no SALVAR do Feegow: ' + (e && e.message)); return false;
    }
  }

  function acharGrupoImpressao(barra) {
    const link = q(barra, SEL.linkImprimirPadrao);
    if (link) {
      const g = link.closest(SEL.grupoImpressao);
      if (g && barra.contains(g)) return g;
      return link;
    }
    return null;
  }

  function injetarNoForm(form) {
    const barra = q(form, SEL.botoes);
    const existente = barra ? q(barra, '.' + CLASSE_BOTAO) : q(form, '.' + CLASSE_BOTAO);
    if (!liberadoParaForm(form)) { if (existente) existente.remove(); qa(form, '.' + CLASSE_BOTAO_GER).forEach((x) => x.remove()); return false; }
    if (existente) { // idempotente (v1.4.0: garante também o botão "Gerenciar descrições" ao lado)
      if (!q(barra || form, '.' + CLASSE_BOTAO_GER)) existente.insertAdjacentElement('beforebegin', criarBotaoGerenciar());
      return false;
    }
    if (!barra) return false;
    const btn = criarBotao(form);
    const grupo = acharGrupoImpressao(barra);
    if (grupo) grupo.insertAdjacentElement('afterend', btn);
    else {
      const salvar = q(barra, SEL.botaoSalvar);
      if (salvar) salvar.insertAdjacentElement('beforebegin', btn); else barra.appendChild(btn);
      log('grupo de impressão padrão não encontrado; botão colocado antes do SALVAR.');
    }
    btn.insertAdjacentElement('beforebegin', criarBotaoGerenciar()); // v1.4.0
    return true;
  }

  let ligado = true;
  function varrer() {
    if (!ligado || !featureAtiva()) return 0;
    let n = 0;
    qa(document, SEL.form).forEach((f) => { if (injetarNoForm(f)) n++; });
    if (n) log('botão "Imprimir HOC Derma" injetado (' + n + ').');
    return n;
  }

